/// Whether a recorded location is still reachable *without creating anything* — the mechanism behind
/// "back ignores what was closed". `step(_:isLive:)` skips every entry this rejects.
///
/// A terminal entry needs its own tab: there is nothing else to show. A content entry needs somewhere
/// to land — a tab already showing it, or a preview slot to retarget — AND its recorded tab must
/// still exist, because `prune` keys on the tab id and an entry that outlived its tab is one the user
/// closed. Deliberately does NOT ask whether the file or commit still exists on disk: that needs I/O
/// inside a predicate run per candidate while stepping, and the pane already renders its own
/// "Diff unavailable" / "Changeset unavailable" state.
private func isLive(_ loc: NavLocation) -> Bool {
  guard let target = target(for: loc.target), !target.isMissing else { return false }
  let tabs = terminals.tabs(for: target)
  guard tabs.contains(where: { $0.id == loc.tab }) else { return false }
  guard let payload = loc.payload else { return true }
  return tabs.contains { payload.matchesTab($0.content) } || terminals.hasPreviewTab(for: target)
}

