/// THE RULE: with every tab pinned there is no preview slot, so the recorded diff has nowhere to
/// land. Back must skip that entry rather than create a tab.
func testReplayNeverCreatesATab() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  let a = SidebarID.workroom(project: "/a", name: "main")
  let targetA = store.target(for: a)!
  let term = addTerminal(store, a)

